// Some portions generated by Claude

// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	repositoryPageUrl,
	serverBaseUrl,
	uniqueRepositoryId
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-sidebar-context');

test.describe.configure({ mode: 'serial' });

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID, { graphs: ['bsbm'] });
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

/** Where the shell's parts sit; the page is scrolled to the top. */
async function shellGeometry(page) {
	return page.evaluate(() => {
		const rect = (selector) => {
			const box = document.querySelector(selector).getBoundingClientRect();
			return { x: box.x, y: box.y, width: box.width, height: box.height, bottom: box.bottom, right: box.right };
		};
		return {
			bar: rect('#workbench-contextbar'),
			menu: rect('#navigation'),
			panel: rect('.workbench-navigation-disclosure'),
			content: rect('#content'),
			title: rect('#title_heading'),
			brand: rect('#logo'),
			repository: rect('#workbench-repository-switcher')
		};
	});
}

test('on a desktop the server and repository switchers sit in the sidebar above the menu and no bar spans the top', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'), { waitUntil: 'networkidle' });
	const shell = await shellGeometry(page);
	// The context block is as wide as the menu and sits directly above it, in the sidebar column.
	expect(Math.abs(shell.bar.x - shell.menu.x), 'the context block shares the menu column').toBeLessThanOrEqual(1);
	expect(Math.abs(shell.bar.width - shell.menu.width), 'the context block is as wide as the menu').toBeLessThanOrEqual(2);
	expect(shell.bar.bottom, 'the menu starts where the context block ends').toBeLessThanOrEqual(shell.menu.y + 1);
	// Brand, then the repository switcher, stacked; there is no server switcher.
	expect(shell.brand.bottom).toBeLessThanOrEqual(shell.repository.y + 1);
	expect(shell.repository.width, 'the switcher fills the sidebar width').toBeGreaterThanOrEqual(shell.bar.width - 26);
	await expect(page.locator('#workbench-server-switcher')).toHaveCount(0);
	// The sidebar is a full-height panel along the left edge, not a floating card.
	expect(shell.bar.x, 'the sidebar starts at the left edge').toBe(0);
	expect(shell.bar.y, 'the sidebar starts at the top edge').toBe(0);
	expect(shell.panel.y + shell.panel.height, 'the sidebar reaches the bottom of the viewport').toBeGreaterThanOrEqual(900);
	// Nothing spans the top of the page: the content column begins at the top of the viewport.
	expect(shell.content.y, 'the page starts at the top of the viewport').toBeLessThanOrEqual(32);
	expect(shell.content.x, 'the page sits beside the sidebar').toBeGreaterThanOrEqual(shell.bar.right);
	expect(shell.title.y, 'the page title is near the top of the viewport').toBeLessThanOrEqual(60);
	await expect(page.locator('#workbench-repository-switcher')).toContainText(REPOSITORY_ID);
});

test('opening the repository switcher widens the sidebar and shows its panel inside the sidebar', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'), { waitUntil: 'networkidle' });
	const before = await shellGeometry(page);
	const width = () => page.locator('#workbench-contextbar').boundingBox().then((box) => box.width);
	await page.locator('#workbench-repository-switcher').click();
	const panel = page.locator('#workbench-repository-popover');
	await expect(panel).toBeVisible();
	await expect.poll(width, { message: 'the sidebar widens' }).toBeGreaterThanOrEqual(before.bar.width + 120);
	// Measure once the widening has finished: the sidebar and its panel are read in separate calls, and mid-way
	// through the transition the panel would already have grown past the width read for the sidebar a moment before.
	await page.waitForFunction(() => [document.body, document.querySelector('#workbench-contextbar')]
		.every((element) => element.getAnimations().length === 0));
	const after = await shellGeometry(page);
	const box = await panel.boundingBox();
	expect(box.x, 'the panel starts inside the sidebar').toBeGreaterThanOrEqual(after.bar.x);
	expect(box.x + box.width, 'the panel ends inside the sidebar').toBeLessThanOrEqual(after.bar.right + 1);
	expect(box.y + box.height).toBeLessThanOrEqual(900);
	expect(after.content.x, 'the page moves over to make room').toBeGreaterThanOrEqual(after.bar.right);
	// The panel names no server or user, and links no page that changes them.
	await expect(panel.locator('.workbench-popover__server')).toHaveCount(0);
	await expect(panel.getByRole('link', { name: /Change server or user/ })).toHaveCount(0);
	await page.keyboard.press('Escape');
	await expect(panel).toBeHidden();
	await expect.poll(width, { message: 'the sidebar narrows again' }).toBeLessThanOrEqual(before.bar.width + 1);
});

test('the sidebar context block and the menu both stay in view while a long page scrolls', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 700 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'types'), { waitUntil: 'networkidle' });
	await page.evaluate(() => { document.body.style.minHeight = '4000px'; });
	const before = await shellGeometry(page);
	await page.evaluate(() => window.scrollTo(0, 1200));
	await expect.poll(() => page.evaluate(() => window.scrollY)).toBe(1200);
	const after = await shellGeometry(page);
	expect(Math.abs(after.bar.y - before.bar.y), 'the context block stays put').toBeLessThanOrEqual(1);
	expect(Math.abs(after.menu.y - before.menu.y), 'the menu stays put').toBeLessThanOrEqual(1);
});

test('on a phone the compact bar with the menu button is unchanged', async ({ page }) => {
	await page.setViewportSize({ width: 390, height: 844 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'), { waitUntil: 'networkidle' });
	const bar = await page.locator('#workbench-contextbar').boundingBox();
	// The bar spans the page. With classic scrollbars (Linux) the root's stable scrollbar gutter takes 15px off the
	// 390px viewport; the body's width leaves it out, while documentElement.clientWidth still reports 390.
	const pageWidth = await page.evaluate(() => document.body.getBoundingClientRect().width);
	expect(bar.width, 'the bar spans the page').toBeGreaterThanOrEqual(pageWidth - 10);
	expect(bar.height).toBeLessThanOrEqual(60);
	await expect(page.locator('#workbench-menu-button')).toBeVisible();
	await expect(page.locator('#workbench-repository-switcher')).toBeVisible();
});
